def compute(vars):
    opening_balance = vars["v1"]
    ending_balance = vars["v2"]
    net_change = ending_balance - opening_balance

    return {
        "value": net_change,
        "trace": {
            "opening_balance": opening_balance,
            "ending_balance": ending_balance,
            "output_meta": {
                "currency": "USD",
                "scale": "thousand",
                "unit": None
            }
        }
    }
